movies |&gt;
  group_by(studio) |&gt;
  summarize(n = n()) |&gt;
  arrange(n) |&gt;
  head(1)

#&gt; # A tibble: 1 × 2
#&gt;   studio             n
#&gt;   &lt;chr&gt;          &lt;int&gt;
#&gt; 1 7-57 Releasing     1

