# install.packages("pointblank")  # once
library(pointblank)

users |&gt;
  create_agent() |&gt;
  col_vals_between(age, 0, 120, na_pass = TRUE) |&gt;
  col_vals_in_set(device, c("watch", "band", "ring")) |&gt;
